//! `ShadowVolumeAppearance` against the pinned CesiumJS cases in
//! `tests/data/scene-shadow-volume-appearance.json` (generated by
//! `tools/cesium/generate-scene-shadow-volume-appearance.mjs`).

use cesium_rs::core::*;
use cesium_rs::renderer::{PickColorQualifier, ShaderSource};
use cesium_rs::scene::{
    Appearance, Fabric, Material, MaterialAppearance, MaterialAppearanceOptions, MaterialOptions,
    PerInstanceColorAppearance, PerInstanceColorAppearanceOptions, ShadowVolumeAppearance,
};
use cesium_rs::shaders::root as root_shaders;
use serde_json::Value;

const FS_MARKER: &str = "<ShadowVolumeAppearanceFS>";

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-shadow-volume-appearance.json")).unwrap()
}

fn number(v: &Value) -> f64 {
    match v {
        Value::String(s) => match s.as_str() {
            "NaN" => f64::NAN,
            "Infinity" => f64::INFINITY,
            "-Infinity" => f64::NEG_INFINITY,
            "-0" => -0.0,
            other => panic!("unexpected number {other}"),
        },
        other => other.as_f64().unwrap(),
    }
}

fn numbers(v: &Value) -> Vec<f64> {
    v.as_array().unwrap().iter().map(number).collect()
}

fn fabric_material(source: &str) -> Material {
    Material::new(MaterialOptions { fabric: Fabric::default().source(source), ..Default::default() })
}

const FABRIC_DIFFUSE_TAIL: &str =
    "m.alpha = 1.0; m.specular = 0.0; m.shininess = 1.0; m.normal = vec3(0.0); m.emission = vec3(0.0); return m; }";

/// The appearances the generator builds, by name.
fn appearance(name: &str, flat: bool) -> Box<dyn Appearance> {
    let material = |material: Material| {
        Box::new(MaterialAppearance::new(MaterialAppearanceOptions {
            flat: Some(flat),
            material: Some(material),
            ..Default::default()
        })) as Box<dyn Appearance>
    };
    match name {
        "perInstance" => Box::new(PerInstanceColorAppearance::new(PerInstanceColorAppearanceOptions {
            flat: Some(flat),
            ..Default::default()
        })),
        "color" => material(Material::from_type("Color")),
        "grid" => material(Material::from_type("Grid")),
        "checkerboard" => material(Material::from_type("Checkerboard")),
        "normalEC" => material(fabric_material(
            "czm_material czm_getMaterial(czm_materialInput materialInput) { czm_material m; m.diffuse = materialInput.normalEC; return m; }",
        )),
        "positionToEyeEC" => material(fabric_material(&format!(
            "czm_material czm_getMaterial(czm_materialInput materialInput) {{ czm_material m; m.diffuse = materialInput.positionToEyeEC; {FABRIC_DIFFUSE_TAIL}"
        ))),
        "tangentToEyeMatrix" => material(fabric_material(
            "czm_material czm_getMaterial(czm_materialInput materialInput) { czm_material m; m.normal = materialInput.tangentToEyeMatrix * vec3(0.0, 0.0, 1.0); m.diffuse = vec3(1.0); m.alpha = 1.0; m.specular = 0.0; m.shininess = 1.0; m.emission = vec3(0.0); return m; }",
        )),
        "st" => material(fabric_material(&format!(
            "czm_material czm_getMaterial(czm_materialInput materialInput) {{ czm_material m; m.diffuse = vec3(materialInput.st, 0.0); {FABRIC_DIFFUSE_TAIL}"
        ))),
        "customFragment" => Box::new(MaterialAppearance::new(MaterialAppearanceOptions {
            flat: Some(flat),
            material: Some(fabric_material(
                "czm_material czm_getMaterial(czm_materialInput i) { czm_material m; m.diffuse = vec3(1.0); m.alpha = 1.0; m.specular = 0.0; m.shininess = 1.0; m.normal = vec3(0.0); m.emission = vec3(0.0); return m; }",
            )),
            fragment_shader_source: Some(
                "void main() { czm_materialInput materialInput; materialInput.st = vec2(0.0); materialInput.positionToEyeEC = vec3(0.0); }"
                    .into(),
            ),
            ..Default::default()
        })),
        other => panic!("unknown appearance {other}"),
    }
}

fn assert_shader(actual: &ShaderSource, expected: &Value, context: &str) {
    assert_eq!(serde_json::json!(actual.defines), expected["defines"], "{context}: defines");
    let sources: Vec<String> = expected["sources"]
        .as_array()
        .unwrap()
        .iter()
        .map(|s| match s.as_str().unwrap() {
            FS_MARKER => root_shaders::SHADOW_VOLUME_APPEARANCE_FS.source.to_string(),
            other => other.to_string(),
        })
        .collect();
    assert_eq!(actual.sources, sources, "{context}: sources");
    let qualifier = actual.pick_color_qualifier.map(|q| match q {
        PickColorQualifier::In => "in",
        PickColorQualifier::Uniform => "uniform",
    });
    assert_eq!(qualifier, expected["pickColorQualifier"].as_str(), "{context}: pickColorQualifier");
}

#[test]
fn shader_sources_match_reference() {
    let fixture = fixture();
    let appearances = fixture["shaders"].as_array().unwrap();
    assert_eq!(appearances.len(), 9);
    let projection = GeographicProjection::default();
    let mut checked = 0;
    for spec in appearances {
        let name = spec["name"].as_str().unwrap();
        for case in spec["cases"].as_array().unwrap() {
            let mask = case["mask"].as_u64().unwrap();
            let (cull, planar, flat, cv) = (mask & 1 != 0, mask & 2 != 0, mask & 4 != 0, mask & 8 != 0);
            let volume = ShadowVolumeAppearance::new(cull, planar, appearance(name, flat));
            let context = format!("{name} mask {mask}");
            assert_shader(&volume.create_fragment_shader(cv), &case["color"], &format!("{context} color"));
            assert_shader(&volume.create_pick_fragment_shader(cv), &case["pick"], &format!("{context} pick"));
            let external = ["EXTERNAL".to_string()];
            let vertex = volume.create_vertex_shader(&external, "void main() {}", cv, &projection);
            assert_shader(&vertex, &case["vertex"], &format!("{context} vertex"));
            let pick = volume.create_pick_vertex_shader(&external, "void main() {}", cv, &projection);
            assert_shader(&pick, &case["pickVertex"], &format!("{context} pick vertex"));
            checked += 1;
        }
    }
    assert_eq!(checked, 144);
}

#[test]
fn projection_extent_defines_come_from_the_first_vertex_shader() {
    let fixture = fixture();
    let case = &fixture["caching"];
    let r = numbers(&case["ellipsoid"]);
    let small = WebMercatorProjection::new(Ellipsoid::new(r[0], r[1], r[2]));
    let per_instance = || Box::new(PerInstanceColorAppearance::new(PerInstanceColorAppearanceOptions::default()));

    let volume = ShadowVolumeAppearance::new(true, false, per_instance());
    let first = volume.create_vertex_shader(&[], "void main() {}", false, &small);
    assert_eq!(serde_json::json!(first.defines), case["first"]);
    // A later call with another projection keeps the first projection's extents.
    let second = volume.create_pick_vertex_shader(&[], "void main() {}", true, &GeographicProjection::default());
    assert_eq!(serde_json::json!(second.defines), case["second"]);

    let fresh = ShadowVolumeAppearance::new(true, false, per_instance());
    let direct = fresh.create_vertex_shader(&[], "void main() {}", true, &small);
    // The west-most high part is -0, which `toFixed` prints without a sign.
    assert_eq!(serde_json::json!(direct.defines), case["direct"]);
}

fn assert_bits(actual: &[f64], expected: &[f64], context: &str) {
    assert_eq!(actual.len(), expected.len(), "{context}: length");
    for (i, (a, e)) in actual.iter().zip(expected).enumerate() {
        assert!(a.to_bits() == e.to_bits() || (a.is_nan() && e.is_nan()), "{context}[{i}]: {a:?} != {e:?}");
    }
}

fn assert_attributes(actual: &[(String, GeometryInstanceAttribute)], expected: &Value, context: &str) {
    let expected = expected.as_array().unwrap();
    let names: Vec<&str> = actual.iter().map(|(n, _)| n.as_str()).collect();
    let expected_names: Vec<&str> = expected.iter().map(|e| e[0].as_str().unwrap()).collect();
    assert_eq!(names, expected_names, "{context}: names in order");
    for ((name, attribute), entry) in actual.iter().zip(expected) {
        let e = &entry[1];
        let context = format!("{context} {name}");
        assert_eq!(attribute.component_datatype as u64, e["componentDatatype"].as_u64().unwrap(), "{context}");
        assert_eq!(u64::from(attribute.components_per_attribute), e["componentsPerAttribute"].as_u64().unwrap());
        assert_eq!(attribute.normalize, e["normalize"].as_bool().unwrap(), "{context}");
        assert!(matches!(attribute.value, TypedArray::Float64(_)), "{context}: plain number array");
        assert_bits(&attribute.value.to_f64_vec(), &numbers(&e["value"]), &context);
    }
}

#[test]
fn texture_coordinate_attributes_match_reference() {
    let fixture = fixture();
    assert_eq!(
        ShadowVolumeAppearance::MAX_WIDTH_FOR_PLANAR_EXTENTS.to_bits(),
        number(&fixture["maxWidthForPlanarExtents"]).to_bits()
    );
    let cases = fixture["attributes"].as_array().unwrap();
    assert_eq!(cases.len(), 24);
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let r = numbers(&case["rectangle"]);
        let rectangle = Rectangle::new(r[0], r[1], r[2], r[3]);
        let rotation: [f64; 6] = numbers(&case["rotation"]).try_into().unwrap();
        let radii = numbers(&case["ellipsoid"]);
        let ellipsoid = Ellipsoid::new(radii[0], radii[1], radii[2]);
        let geographic = GeographicProjection::new(ellipsoid);
        let mercator = WebMercatorProjection::new(ellipsoid);
        let projection: &dyn MapProjection = if case["projection"] == "webMercator" { &mercator } else { &geographic };
        let height = case["height"].as_f64();

        assert_eq!(
            ShadowVolumeAppearance::should_use_spherical_coordinates(&rectangle),
            case["shouldUseSpherical"].as_bool().unwrap(),
            "{name}"
        );
        let planar = ShadowVolumeAppearance::get_planar_texture_coordinate_attributes(
            &rectangle, &rotation, &ellipsoid, projection, height,
        )
        .unwrap();
        assert_attributes(&planar, &case["planar"], &format!("{name} planar"));
        let spherical = ShadowVolumeAppearance::get_spherical_extent_geometry_instance_attributes(
            &rectangle, &rotation, &ellipsoid, projection,
        )
        .unwrap();
        assert_attributes(&spherical, &case["spherical"], &format!("{name} spherical"));

        for (attributes, planes, spheres) in [
            (&planar, "planarHasPlanes", "planarHasSpherical"),
            (&spherical, "sphericalHasPlanes", "sphericalHasSpherical"),
        ] {
            assert_eq!(
                ShadowVolumeAppearance::has_attributes_for_texture_coordinate_planes(attributes),
                case[planes].as_bool().unwrap(),
                "{name} {planes}"
            );
            assert_eq!(
                ShadowVolumeAppearance::has_attributes_for_spherical_extents(attributes),
                case[spheres].as_bool().unwrap(),
                "{name} {spheres}"
            );
        }
    }
}
